int main() {
    string vlan_pool_input;
    vector<pair<int, int> > ans;
    int needVlanId ;
​
    cin>>vlan_pool_input; 
    vector<string> splitResult = split(vlan_pool_input, ',');
    // 这段代码是将资源池按照`,`进行分割并转换为区间
    for (int i = 0; i < splitResult.size(); i++) {
        string tmp = splitResult[i];
        if (tmp.find('-') != -1) {
            vector<string> result = split(tmp, '-');
            ans.push_back({stringToInt(result[0]), stringToInt(result[1])});
        } else {
            ans.push_back({stringToInt(tmp), stringToInt(tmp)});
        }
    }

    cin >> needVlanId;
    // 将区间进行排序
    sort(ans.begin(), ans.end(), cmp);
    bool flag = false;
​
    for (int i = 0; i < ans.size(); i++) {
        pair<int, int> p = ans[i];
        int first = p.first;
        int second = p.second;
        if (needVlanId >= first && needVlanId <= second) {
            int right1 = needVlanId -1;
            int left2 = needVlanId + 1;      
            outputformt(first, right1, flag);
            outputformt(left2, second, flag);
        } else {
            outputformt(first, second, flag);
        }
    }

    return 0;
}
