package main
​
import (
    "fmt"
    "sort"
    "strconv"
    "strings"
)
​
func processVlanPool(vlanPoolInput string, needVlanId int) string {
    // 分割输入并处理为区间
    var ranges [][]int
    for _, part := range strings.Split(vlanPoolInput, ",") {
        if strings.Contains(part, "-") {
            bounds := strings.Split(part, "-")
            start, _ := strconv.Atoi(bounds[0])
            end, _ := strconv.Atoi(bounds[1])
            ranges = append(ranges, []int{start, end})
        } else {
            value, _ := strconv.Atoi(part)
            ranges = append(ranges, []int{value, value})
        }
    }
​
    // 排序区间
    sort.Slice(ranges, func(i, j int) bool {
        return ranges[i][0] < ranges[j][0]
    })
​
    // 合并和处理区间
    var result []string
    for _, r := range ranges {
        start, end := r[0], r[1]
        if needVlanId >= start && needVlanId <= end {
            // 左区间的右边界
            leftSectionRight := needVlanId - 1
            // 右区间的左边界
            rightSectionLeft := needVlanId + 1
            //处理区间的问题
            if leftSectionRight > start {
                result = append(result, fmt.Sprintf("%d-%d", start, leftSectionRight))
            } else if leftSectionRight == start {
                result = append(result, fmt.Sprintf("%d", start))
            }
​
            if rightSectionLeft < end {
                result = append(result, fmt.Sprintf("%d-%d", rightSectionLeft, end))
            } else if rightSectionLeft == end {
                result = append(result, fmt.Sprintf("%d", end))
            }
        } else {
            if start == end {
                result = append(result, fmt.Sprintf("%d", start))
            } else {
                result = append(result, fmt.Sprintf("%d-%d", start, end))
            }
        }
    }
​
    // 返回结果
    return strings.Join(result, ",")
}
​
func main() {
    // 输入 VLAN 资源池
    var vlanPoolInput string
    fmt.Scanln(&vlanPoolInput)
​
    // 输入需要移除的 VLAN ID
    var needVlanId int
    fmt.Scanln(&needVlanId)
​
    // 处理并输出结果
    output := processVlanPool(vlanPoolInput, needVlanId)
    fmt.Println(output)
}
